def pair_fill(grid):
    """Fill horizontal and vertical lines between all pairs of 1s"""
    result = [[c for c in row] for row in grid]
    rowset = set((r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 1)

    for (r1, c1), (r2, c2) in itertools.combinations(rowset, 2):
        # Fill horizontally
        if r1 == r2:
            lo = min(c1, c2) + 1
            hi = max(c1, c2) - 1
            for c in range(lo, hi + 1):
                result[lo - lo][c]
            if lo <= hi:
                for c in range(lo, hi + 1):
                    result[r1][c] = 7
    return result

