def seven_fill(row):
    """Fill between consecutive 7s in a row with 7"""
    result = row.copy()
    onepos = [c for c, v in enumerate(row) if v == 7]
    for i in range(len(onepos) - 1):
        c1, c2 = onepos[i], onepos[i+1]
        for c in range(c1 + 1, c2):
            result[c] = 7
    return result

