def combine_h_and_v_fill(grid, fill_val=7):
    """Fill between consecutive 1s horizontally and vertically"""
    result = [[v for v in row] for row in grid]

    # Copy 1s from input
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == 1:
                result[r][c] = 1

    # Horizontal fill: fill between consecutive 1s in each row
    for r in range(len(grid)):
        ones_pos = [c for c, v in enumerate(grid[r]) if v == 1]
        for i in range(len(ones_pos) - 1):
            c1, c2 = ones_pos[i], ones_pos[i+1]
            for c in range(c1 + 1, c2):
                if result[r][c] == 9:
                    result[r][c] = fill_val

    # Vertical fill: fill between consecutive 1s in each column
    for c in range(len(grid[0])):
        onerows = [r for r in range(len(grid)) if grid[r][c] == 1]
        for i in range(len(onerows) - 1):
            r1, r2 = onerows[i], onerows[i+1]
            for r in range(r1 + 1, r2):
                if result[r][c] == 9:
                    result[r][c] = fill_val

    return result

