def fill_between_markers(grid, bg_val):
    """Fill with bg_val between consecutive markers in rows/cols"""
    result = [[v for v in row] for row in grid]

    # Find all marker values (non-background) in the entire grid
    marker_vals = set()
    for row in grid:
        for v in row:
            if v != bg_val:
                marker_vals.add(v)

    for r in range(len(result)):
        marker_cols = [c for c, v in enumerate(grid[r]) if v in marker_vals]
        for i in range(len(marker_cols) - 1):
            c1, c2 = marker_cols[i], marker_cols[i+1]
            for c in range(c1 + 1, c2):
                if result[r][c] == bg_val:
                    result[r][c] = bg_val

    for c in range(len(grid[0])):
        marker_rows = [r for r in range(len(grid)) if grid[r][c] in marker_vals]
        for i in range(len(marker_rows) - 1):
            r1, r2 = marker_rows[i], marker_rows[i+1]
            for r in range(r1 + 1, r2):
                if result[r][c] == bg_val:
                    result[r][c] = bg_val

    return result

